    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260825132758_InitialCreate') THEN
    CREATE UNIQUE INDEX "IX_CardProgresses_CardId_UserId" ON "CardProgresses" ("CardId", "UserId");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260825132758_InitialCreate') THEN
